<?php require_once __DIR__.'/config/security.php'; require_permission('permissions.manage'); $rows=$pdo->query('SELECT * FROM permissions ORDER BY role,permission_key')->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Permission Center</h1><p>Manage role-based access without changing application code.</p></div></div>
<div class="panel"><div class="toolbar"><input id="permRole" class="search" placeholder="Role e.g. IT Staff"><input id="permKey" class="search" placeholder="Permission e.g. reports.view"><button class="btn primary" onclick="addPermission()">Add Permission</button></div><div class="table-wrap"><table><thead><tr><th>Role</th><th>Permission</th><th>Action</th></tr></thead><tbody id="permRows"><?php foreach($rows as $r): ?><tr><td><span class="role-badge"><?=htmlspecialchars($r['role'])?></span></td><td><?=htmlspecialchars($r['permission_key'])?></td><td><?php if($r['permission_key']!=='*'): ?><button class="icon-btn danger" onclick='removePermission(<?=json_encode($r['role'])?>,<?=json_encode($r['permission_key'])?>)'>Revoke</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<script>
async function addPermission(){const role=document.getElementById('permRole').value.trim(),permission_key=document.getElementById('permKey').value.trim();const r=await fetch('api/permissions.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role,permission_key})});const j=await r.json();if(!j.ok)return toast(j.message,true);location.reload();}
async function removePermission(role,permission_key){if(!confirm('Revoke '+permission_key+' from '+role+'?'))return;const r=await fetch('api/permissions.php',{method:'DELETE',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({role,permission_key})});const j=await r.json();if(!j.ok)return toast(j.message,true);location.reload();}
</script><?php include __DIR__.'/partials/footer.php'; ?>
